'use strict';

// MODULES //

var coshf = require( '@stdlib/math-base-special-coshf' );
var f32 = require( '@stdlib/number-float64-base-to-float32' );


// VARIABLES //

var ONE = f32( 1.0 );


// MAIN //

/**
* Computes the hyperbolic secant of a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} hyperbolic secant
*
* @example
* var v = sechf( 0.0 );
* // returns 1.0
*
* @example
* var v = sechf( 2.0 );
* // returns ~0.2658
*
* @example
* var v = sechf( -2.0 );
* // returns ~0.2658
*
* @example
* var v = sechf( NaN );
* // returns NaN
*/
function sechf( x ) {
	return f32( ONE / coshf( f32( x ) ) );
}


// EXPORTS //

module.exports = sechf;
